import pathlib,json,datetime
R=pathlib.Path(__file__).resolve().parents[1];u=json.loads((R/'normalized/fund_combined_current_universe.json').read_text())['items'];requested={x['code'] for x in u};direct={}
for l in (R/'logs/fund-receipts.jsonl').read_text().splitlines():
 x=json.loads(l);direct[x['code']]=x
